import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, qty, seq, active)
    book_buy = []   # heap of (-price, seq, id)
    book_sell = []  # heap of (price, seq, id)

    def match_incoming(side, price, qty, id_, is_market):
        result_trades = []
        heap = book_sell if side == 'buy' else book_buy
        while qty > 0 and heap:
            top = heap[0]
            oid = top[2]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            resting_price = info['price']
            if is_market:
                price_ok = True
            else:
                if side == 'buy':
                    price_ok = resting_price <= price
                else:
                    price_ok = resting_price >= price
            if not price_ok:
                break
            trade_qty = min(qty, info['qty'])
            if side == 'buy':
                result_trades.append([id_, oid, resting_price, trade_qty])
            else:
                result_trades.append([oid, id_, resting_price, trade_qty])
            qty -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(heap)
            # if incoming qty is now 0, loop will exit naturally
        return qty, result_trades

    seq = 0
    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, id_, side, price, qty = order
            remaining, tr = match_incoming(side, price, qty, id_, is_market=False)
            trades.extend(tr)
            if remaining > 0:
                info = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                orders_info[id_] = info
                if side == 'buy':
                    heapq.heappush(book_buy, (-price, seq, id_))
                else:
                    heapq.heappush(book_sell, (price, seq, id_))
        elif typ == 'ioc':
            _, id_, side, price, qty = order
            remaining, tr = match_incoming(side, price, qty, id_, is_market=False)
            trades.extend(tr)
            # remainder discarded, not added to book
        elif typ == 'market':
            _, id_, side, qty = order
            remaining, tr = match_incoming(side, None, qty, id_, is_market=True)
            trades.extend(tr)
            # remainder discarded

        seq += 1

    return trades

